let session = null,openSequence=0;
let rosterDrafts=new (require('./form_drafts').FormDrafts)();
const draftKey=document=>document.uri.toString();
function safe(value) { return JSON.stringify(value).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026'); }
function payload(document, preview = {}) { const model = parseSelectDef(document.getText()); return { orderDraft:rosterDrafts.read(draftKey(document)), sourceHash: hash(document.getText()), file: path.basename(document.fileName), uri: document.uri.toString(), ...model, orders: orderGroups(model), preview }; }
function configPreview(selectFilename) {
  const root = gameRoot(selectFilename), filename = root && path.join(root, 'save', 'config.ini');
  if (!filename || !fs.existsSync(filename)) return { state: 'missing', detail: 'save/config.ini was not found for this IKEMEN installation.', filename: filename || '' };
  const sections = []; let current = null;
  for (const raw of fs.readFileSync(filename, 'utf8').split(/\r?\n/)) {
    const section = /^\s*\[([^\]]+)\]/.exec(raw);
    if (section) { current = { name: section[1].trim(), entries: [] }; sections.push(current); continue; }
    const entry = /^\s*([^;#][^=]*?)\s*=\s*(.*?)\s*$/.exec(raw);
    if (current && entry) current.entries.push({ name: entry[1].trim(), value: entry[2].trim() });
  }
  return { state: 'ready', filename, detail: path.relative(root, filename).replace(/\\/g, '/'), sections };
}
async function buildPayload(document, motifFile = '') {
  const model = parseSelectDef(document.getText());
  const resolvedMotif = motifFile || await locateCharacterSelectMotif(document.uri);
  const motif = motifPreview(resolvedMotif);
  return { ...payload(document, { motif, ...rosterPreview(document.fileName, model, motif), config: configPreview(document.fileName) }), paletteCandidates: [] };
}

