function persistOrder(){orderDraft=dirty?{uri:model.uri,sourceHash:orderDraft?.sourceHash||model.sourceHash,lines:[...workingLines],names:workingLines.map(line=>model.characters.find(item=>item.line===line)?.name||String(line))}:null;saveState({});vscode.postMessage({type:'rosterOrderDraft',draft:orderDraft});}
function receiveRosterModel(next){if(dirty){if(next.uri!==model.uri){pendingModel=next;orderConflict=true;}else if(next.sourceHash!==model.sourceHash){pendingModel=next;orderConflict=true;}else model=next;}else{model=next;resetOrder();}render();}
