function badges(e){return [e.order&&'order '+e.order,e.hidden&&'hidden '+e.hidden,e.bonus&&'bonus',e.exclude&&'excluded',e.inSlot&&'slot'].filter(Boolean).map(x=>'<span class="badge">'+esc(x)+'</span>').join('')}
  function actions(e){return '<div class="actions"><button data-act="reveal" data-line="'+e.line+'">Reveal</button>'+(e.kind==='character'?'<button data-act="stages" data-line="'+e.line+'">Assign stages</button><button data-act="order" data-line="'+e.line+'">Set order</button><button data-act="visibility" data-line="'+e.line+'">Visibility</button>'+(e.inSlot?'<button data-act="slotControls" data-line="'+e.line+'">Slot controls</button><button data-act="addSlotAlternate" data-line="'+e.line+'">Add alternate</button>':'<button data-act="makeSlot" data-line="'+e.line+'">Make slot</button>'):'')+'<button data-act="edit" data-line="'+e.line+'">Edit raw line</button><button data-act="up" data-line="'+e.line+'">↑</button><button data-act="down" data-line="'+e.line+'">↓</button><button data-act="delete" data-line="'+e.line+'">Remove</button></div>'}
