function list(entries,empty){if(tab==='stages')return stageList(entries,empty);const q=$('search').value.toLowerCase(),shown=entries.filter(e=>(e.code+' '+e.name).toLowerCase().includes(q));return '<div class="grid">'+(shown.map(e=>card(e,e.stages?.length?'<p><b>Stages:</b> '+esc(e.stages.join(', '))+'</p>':'')).join('')||'<p class="muted">'+empty+'</p>')+'</div>'}
function stageList(entries,empty){const q=$('search').value.toLowerCase(),shown=entries.filter(e=>(e.code+' '+e.name).toLowerCase().includes(q));return '<div class="grid">'+(shown.map(e=>{const p=model.preview?.stagePortraits?.[String(e.line)],visual=['ready','generated'].includes(p?.state)?'<img class="stage-thumb" src="'+p.src+'" title="'+esc(p.detail)+(p.generated?' · generated static preview':'')+'">':'<div class="stage-thumb muted">'+esc(p?.state==='archive'?'ZIP':p?.detail||'No portrait')+'</div>';return '<article class="card stage-card">'+visual+'<div><h3>'+esc(p?.detail||e.name)+'</h3><div class="raw">'+esc(e.code)+'</div>'+actions(e)+'</div></article>'}).join('')||'<p class="muted">'+empty+'</p>')+'</div>'}
function orderedCells(){const source=new Map((model.preview?.cells||[]).filter(x=>x.draggable).map(x=>[x.line,x])),queue=workingLines.map(x=>source.get(x));return (model.preview?.cells||[]).map(x=>x.draggable?queue.shift():x)}
