function selectedDetails(){const lines=[...selectedLines],entries=lines.map(line=>model.characters.find(x=>x.line===line)).filter(Boolean);if(!entries.length)return '<div class="selected-details"><h3>Character properties</h3><p class="muted">Select a portrait to inspect or edit it.</p></div>';const one=entries.length===1?entries[0]:null,buttons='<div class="actions"><button data-bulk-act="bulkStages">Assign stage</button><button data-bulk-act="bulkOrder">Set order</button><button data-bulk-act="bulkVisibility">Visibility</button></div>';if(!one)return '<div class="selected-details"><h3>'+entries.length+' characters selected</h3><p class="muted">These changes will be applied to the complete selection.</p>'+buttons+'</div>';const portrait=model.preview?.portraits?.['line-'+one.line];return '<div class="selected-details"><h3>'+esc(portrait?.detail||one.name)+'</h3><div class="property-grid"><b>Path</b><span>'+esc(one.name)+'</span><b>Order</b><span>'+esc(one.order||'automatic')+'</span><b>Stage</b><span>'+esc(one.stages.join(', ')||'normal selection')+'</span><b>Hidden</b><span>'+esc(one.hidden||'no')+'</span><b>Excluded</b><span>'+esc(one.exclude||'no')+'</span></div>'+buttons+'<div class="actions"><button data-act="reveal" data-line="'+one.line+'">Show code</button><button data-act="edit" data-line="'+one.line+'">Advanced line edit</button></div></div>'}
function previewMarkup(){const p=model.preview||{},m=p.motif||{};if(m.state!=='ready')return '<section class="card warning"><h2>Select-screen preview unavailable</h2><p>'+esc(m.detail||'No active motif was found.')+'</p><button data-preview-refresh>Try motif again</button></section>';const g=m.grid,capacity=Math.max(1,g.rows*g.columns-(g.skippedCells?.length||0)),total=Math.max(1,Math.ceil((p.cells?.length||0)/capacity));page=Math.max(0,Math.min(page,total-1));return '<section class="preview-panel">'+inventoryMarkup()+'<div class="screen-column"><div class="screen-toolbar"><b>Motif-backed select preview</b><button data-page="prev">← Page</button><span>Page '+(page+1)+' / '+total+'</span><button data-page="next">Page →</button><button id="zoomOut">−</button><span id="zoomLabel">'+Math.round(zoom*100)+'%</span><button id="zoomIn">+</button><button id="fitView">Fit</button><button id="toggleNames" class="'+(showCellNames?'active':'')+'" title="Show or hide names drawn over small portraits">Names</button><button id="toggleNumbers" class="'+(showCellNumbers?'active':'')+'" title="Show or hide roster slot numbers drawn over small portraits">Numbers</button><span class="'+(dirty?'dirty':'muted')+'">'+(orderConflict?'Source changed — saved preview retained. Discard it to use the latest roster.':dirty?'Unsaved preview order':'Order matches select.def')+'</span></div><div class="screen-viewport" id="screenViewport"><div class="screen-frame" id="screenFrame"><canvas id="motifCanvas" width="'+m.localCoord[0]+'" height="'+m.localCoord[1]+'"></canvas><canvas id="portraitCanvas" width="'+m.localCoord[0]+'" height="'+m.localCoord[1]+'"></canvas><div class="cell-layer" id="cellLayer"></div><canvas id="motifForeground" width="'+m.localCoord[0]+'" height="'+m.localCoord[1]+'"></canvas></div></div></div><aside class="preview-side"><h3>Safe roster placement</h3><p>Drag one portrait—or Ctrl/Shift-select several—onto a cyan cell to reorder them. Keyboard: Tab to a portrait or character row; Enter or Space selects it (Ctrl/Shift also work). Alt+Up/Down moves the selected characters in the preview. Drag a stage onto selected portraits to assign it.</p><div class="actions"><button class="primary" id="applyOrder" '+(dirty&&!orderConflict?'':'disabled')+'>Review & apply roster order</button><button id="discardOrder" '+(dirty?'':'disabled')+'>Discard preview order</button><button data-preview-refresh>Refresh portraits</button></div><p><b>Motif:</b> '+esc(m.detail)+'<br><b>Canvas:</b> '+m.localCoord.join(' × ')+' · uniformly scaled<br><b>Motif graphics:</b> '+(m.backgrounds?.length||0)+' background layers<br><b>Grid:</b> '+g.columns+' × '+g.rows+' · usable '+capacity+'<br><b>Small portrait:</b> '+m.portraitSpec.sprite.join(',')+' · scale '+m.portraitSpec.scale.join(',')+'<br><b>Large portraits:</b> '+(m.faceSpecs?.p1?.sprite||[9000,1]).join(',')+'</p>'+selectedDetails()+'<div class="legend"><span class="swatch"></span><span>Normal draggable cell</span><span class="swatch locked"></span><span>Slot or hidden/locked cell</span><span class="swatch skipped"></span><span>Motif skipped cell</span></div><p class="muted">The preview reads motif coordinates, background and foreground graphics, cell art, and small and large portraits. Dynamic Lua and animation timing remain authoritative in IKEMEN.</p></aside></section>'}
function stagePreviewMarkup(){return previewMarkup().replace('Safe roster placement','Stage assignments').replace('Drag one portrait—or Ctrl/Shift-select several—onto a cyan cell to reorder them. Keyboard: Tab to a portrait or character row; Enter or Space selects it (Ctrl/Shift also work). Alt+Up/Down moves the selected characters in the preview. Drag a stage onto selected portraits to assign it.','Select one portrait—or Ctrl/Shift-select several—then drag the portrait selection from the select screen onto a stage at left. You can also drag a stage back onto a portrait.').replace('Order matches select.def','Select screen remains fully interactive')}
