function optionsMarkup(){const config=model.preview?.config||{},normal=(config.sections||[]).find(s=>s.name.toLowerCase()==='options'),advanced=(config.sections||[]).filter(s=>s!==normal);return '<section class="card"><h2>Game Options</h2><p>These values come from <b>save/config.ini [Options]</b>, the current IKEMEN 1.0 replacement for MUGEN.cfg. The normal in-game Options menu writes into this configuration.</p><div class="actions"><button class="primary" data-open-config>Open config.ini</button></div>'+(normal?configRows(normal):'<p class="warning">'+esc(config.detail||'Game configuration was not found.')+'</p>')+'</section><section class="card"><h2>Advanced engine configuration</h2><p class="muted">Video, sound, input, arcade, netplay, debug, common-file, and engine settings also live in config.ini. They are collapsed below because many are not ordinary player-facing options.</p>'+advanced.map(configRows).join('')+'</section><section class="card"><h2>select.def [Options]</h2><p class="muted">These are roster and mode-matching rules, not the general game Options menu.</p><button data-add="options">+ Add select.def option</button>'+list(model.options,'No select.def options match.')+'</section>'}
function detailedRosterMarkup(){let title='Characters',body='';if(inventoryTab==='orders'){title='Arcade Orders';body=model.orders.map(g=>'<section class="lane"><h2>Order '+esc(g.order)+'</h2>'+list(g.entries,'No entries')+'</section>').join('')||'<p class="muted">No character order assignments.</p>'}else if(inventoryTab==='stages'){title='Stages';body=stageList(model.stages,'No extra stages match.')}else if(inventoryTab==='excluded'){title='Excluded';body=list(model.characters.filter(x=>String(x.exclude||'0')==='1'),'No excluded characters.')}else body=list(model.characters.filter(x=>String(x.exclude||'0')!=='1'),'No character entries match.');return '<details class="card"><summary><b>Detailed '+title+' list</b> · optional card view</summary>'+body+'</details>'}
